package vn.covie.notifications.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notification_deliveries") public class NotificationDeliveryEntity { @Id private UUID id; @Column(name="notification_id",nullable=false) private UUID notificationId; @Enumerated(EnumType.STRING) @Column(nullable=false) private NotificationChannel channel; @Enumerated(EnumType.STRING) @Column(name="delivery_status",nullable=false) private NotificationDeliveryStatus deliveryStatus; @Column(name="attempted_at") private Instant attemptedAt; @Column(name="delivered_at") private Instant deliveredAt; @Column(name="failure_code") private String failureCode; protected NotificationDeliveryEntity(){} public static NotificationDeliveryEntity deliveredInApp(UUID id,UUID notificationId,Instant now){NotificationDeliveryEntity d=new NotificationDeliveryEntity();d.id=id;d.notificationId=notificationId;d.channel=NotificationChannel.IN_APP;d.deliveryStatus=NotificationDeliveryStatus.DELIVERED;d.attemptedAt=now;d.deliveredAt=now;return d;} }
